      SUBROUTINE MVZEROCC     ZEROS INDIVIDUAL TRANSFER MATRIXCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'      INCLUDE 'T.CIN'      INCLUDE 'U.CIN'CC-----------------------------------------------------------------      LV = 0.0      DO 10 J = 1, 6   10 CODV(J) = 0.0      DO 20 JK = 1, 36   20 RVL(JK) = 0.0      IF (NORD1 .GE. 2) THEN        DO 30 JKM = 1, 105   30   TVL(JKM) = 0.0      ENDIF      IF (NORD1 .GE. 3) THEN        DO 40 JKLM = 1, 280   40   UVL(JKLM) = 0.0      ENDIFC      RETURN      END